                    .subtract(new BigDecimal(parts[1].trim()));
            List<Instalment> reworked = amortise(left, dues.subList(kept, dues.size()),
                    schedule.get(kept).number());
            schedule = new ArrayList<>(schedule.subList(0, kept));
            schedule.addAll(reworked);
